523	// ProcessEntry 由接班人逐项处理交接事项，须填写操作人。
524	// action 为 confirm（确认接收）、return（退回，须填原因）或 track（继续跟踪，须填跟踪说明和后续负责人）。
525	// 已退回项表示等待交班人补充，只有在原交接记录上成功重新提交、恢复待处理后才能再次
526	// 确认、继续跟踪或退回；未重新提交前直接处理一律返回状态错误，且不改变任何数据。
527	// 最后一项成功接收使整份交接首次全部明确接收时，完成时间记为本次成功处理时间；
528	// 若记录里存在补齐前误写（或零值）的旧完成时间，一并以本次时间覆盖。本次处理失败、
529	// 退回或仍有未接收项时不写完成时间，交接不能提前完成。
530	func (svc *Service) ProcessEntry(handoverID, itemID string, action EntryAction, operator, reason, trackingNote, nextFollowOwner string) (Handover, error) {
531		handoverID = clean(handoverID)
532		itemID = clean(itemID)
533		operator = clean(operator)
534		reason = clean(reason)
535		trackingNote = clean(trackingNote)
536		nextFollowOwner = clean(nextFollowOwner)
537	
538		if action != ActionConfirm && action != ActionReturn && action != ActionTrack {
539			return Handover{}, fmt.Errorf("%w：未知操作 %q", ErrInvalidInput, action)
540		}
541		if err := requireNonEmpty("操作人", operator); err != nil {
542			return Handover{}, err
543		}
544	
545		var result Handover
546		err := svc.store.mutate(func(d *Data) error {
547			h, _ := findHandover(d, handoverID)
548			if h == nil {
549				return fmt.Errorf("%w：交接 %s", ErrNotFound, handoverID)
550			}
551			e, _ := findEntry(h, itemID)
552			if e == nil {
553				return fmt.Errorf("%w：交接 %s 中没有事项 %s", ErrNotFound, h.ID, itemID)
554			}
555			if e.Status.Received() {
556				return fmt.Errorf("%w：事项 %s 已%s，不能重复处理或退回",
557					ErrHandoverState, e.ItemID, e.Status.Label())
558			}
559			if e.Status == EntryReturned {
560				// 退回表示等待交班人补充：必须先在原交接记录上补充说明并重新提交，
561				// 该项恢复待处理后才能再次确认、继续跟踪或退回。即使本次填写了
562				// 操作人、退回原因或跟踪说明，也不能跳过这一步。
563				return fmt.Errorf("%w：事项 %s 已退回，正等待交班人补充说明并在原交接记录 %s 上重新提交；请先完成补充并重新提交后再处理",
564					ErrHandoverState, e.ItemID, h.ID)
565			}
566			switch action {
567			case ActionReturn:
568				if err := requireNonEmpty("退回原因", reason); err != nil {
569					return err
570				}
571			case ActionTrack:
572				if err := requireNonEmpty("跟踪说明", trackingNote); err != nil {
573					return err
574				}
575				if err := requireNonEmpty("后续负责人", nextFollowOwner); err != nil {
576					return err
577				}
578			}
579	
580			now := svc.now()
581			switch action {
582			case ActionConfirm:
583				e.Status = EntryConfirmed
584			case ActionTrack:
585				e.Status = EntryTracking
586				e.TrackingNote = trackingNote
587				e.FollowOwner = nextFollowOwner
588			case ActionReturn:
589				e.Status = EntryReturned
590				e.Rounds = append(e.Rounds, ReturnRound{
591					Seq:            len(e.Rounds) + 1,
592					ReturnedAt:     now,
593					ReturnOperator: operator,
594					Reason:         reason,
595				})
596			}
597			e.Operator = operator
598			e.ProcessedAt = &now
599	
600			if action != ActionReturn {
601				// 确认与继续跟踪都进入接班班次的未关闭清单，保留原编号与历史。
602				if it, _ := findItem(d, e.ItemID); it != nil && it.CurrentShiftID == h.FromShiftID {
603					it.CurrentShiftID = h.ToShiftID
604					if !contains(it.ShiftIDs, h.ToShiftID) {
605						it.ShiftIDs = append(it.ShiftIDs, h.ToShiftID)
606					}
607					detail := "接班班次 " + h.ToShiftID + " 接收：" + e.Status.Label()
608					if action == ActionTrack {
609						// 继续跟踪指定新的后续负责人，回写到事项并保留跟踪说明。
610						it.FollowOwner = nextFollowOwner
611						detail += "；跟踪说明：" + trackingNote + "；后续负责人：" + nextFollowOwner
612					}
613					it.Events = append(it.Events, ItemEvent{At: now, Kind: "received", Operator: operator, Detail: detail})
614				}
615			}
616	
617			if h.Completed() {
618				// 完成时间记录这份交接真正接收齐全部事项的时刻：以最后一次成功
619				// 接收（确认或继续跟踪）的处理时间为准。旧数据可能在清单仍有结果
620				// 缺失、无法识别、待处理或退回项时就误写过完成时间（或只留下零值）：
621				// 接班人逐项补齐、整份交接首次全部明确接收时，用本次成功处理时间
622				// 覆盖那个旧时间，不能沿用补齐前的时刻；旧时间缺失（nil）时同样在
623				// 本次补上。未全部接收（如本次退回、仍有异常结果项）时不写入，
624				// 交接保持未完成。正常流程与空清单在首次全部接收时写入，之后已接收
625				// 项无法再处理，完成时间不会被改写。
626				h.CompletedAt = &now
627			}
628			result = *h
629			return nil
630		})
631		return result, err
632	}
633	
634	// validProcessedAt 报告处理时间是否真实记录：nil 或零值
635	// （0001-01-01T00:00:00Z）都视为未记录，不推测补齐。
636	func validProcessedAt(t *time.Time) bool { return t != nil && !t.IsZero() }
637	
638	func contains(xs []string, x string) bool {
639		for _, v := range xs {
640			if v == x {
641				return true
642			}
643		}
644		return false
645	}
646	
647	// ResubmitReturned 由交班人对退回项追加非空说明并在同一交接记录上重新提交；
648	// 补充写入最近一次退回记录（保留该轮原因、退回人和退回时间，并记录补充人、
649	// 补充时间与重新提交时间），以前各轮说明不覆盖。只有该项恢复待处理，当前结果的
650	// 接班处理人与处理时间显示为尚未处理；原文、严重程度、限制条件不变，事项仍留在
651	// 交班班次，同一交接的其他事项不受影响。重新提交本身不表示接收。
652	// 对待处理、已确认或继续跟踪的事项重新提交报状态错误，不写入补充说明。
653	func (svc *Service) ResubmitReturned(handoverID, itemID, operator, supplement string) (Handover, error) {
654		handoverID = clean(handoverID)
655		itemID = clean(itemID)
656		operator = clean(operator)
657		supplement = clean(supplement)
658		if err := requireNonEmpty("操作人", operator); err != nil {
659			return Handover{}, err
660		}
661		if err := requireNonEmpty("补充说明", supplement); err != nil {
662			return Handover{}, err
663		}
664	
665		var result Handover
666		err := svc.store.mutate(func(d *Data) error {
667			h, _ := findHandover(d, handoverID)
668			if h == nil {
669				return fmt.Errorf("%w：交接 %s", ErrNotFound, handoverID)
670			}
671			e, _ := findEntry(h, itemID)
672			if e == nil {
673				return fmt.Errorf("%w：交接 %s 中没有事项 %s", ErrNotFound, h.ID, itemID)
674			}
675			if e.Status != EntryReturned {
676				return fmt.Errorf("%w：事项 %s 当前状态为 %s，只有退回项可以补充说明后重新提交",
677					ErrHandoverState, e.ItemID, e.Status.Label())
678			}
679			if len(e.Rounds) == 0 {
680				return fmt.Errorf("%w：事项 %s 缺少退回记录", ErrHandoverState, e.ItemID)
681			}
682			round := &e.Rounds[len(e.Rounds)-1]
683			if round.ResubmittedAt != nil {
684				return fmt.Errorf("%w：事项 %s 已重新提交，等待接班人处理", ErrHandoverState, e.ItemID)
685			}
686			now := svc.now()
687			round.Supplement = supplement
688			round.SupplementOperator = operator
689			round.SupplementAt = &now
690			round.ResubmittedAt = &now
691			// 仅这一个事项恢复待处理：当前结果的接班处理人与处理时间显示为
692			// 尚未处理；上一轮退回信息仍完整保留在 Rounds 历史中。
693			e.Status = EntryPending
694			e.Operator = ""
695			e.ProcessedAt = nil
696			result = *h
697			return nil
698		})
699		return result, err
700	}
701	
702	// GetShift 按编号查询班次。
703	func (svc *Service) GetShift(id string) (Shift, error) {
704		sh, _ := findShift(&svc.store.data, clean(id))
705		if sh == nil {
706			return Shift{}, fmt.Errorf("%w：班次 %s", ErrNotFound, id)
707		}
708		return *sh, nil
709	}
710	
711	// ListShifts 返回全部班次，按编号排序。
712	func (svc *Service) ListShifts() []Shift {
713		out := append([]Shift(nil), svc.store.data.Shifts...)
714		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
715		return out
716	}
717	
718	// GetItem 按稳定编号查询事项。
719	func (svc *Service) GetItem(id string) (Item, error) {
720		it, _ := findItem(&svc.store.data, clean(id))
721		if it == nil {
722			return Item{}, fmt.Errorf("%w：事项 %s", ErrNotFound, id)
723		}
724		return *it, nil
725	}
726	
727	// ItemJourney 凭事项编号汇总它从建立到当前的处理经过：保留事项自身的
728	// 建立、修改、关闭记录，并加入它参与的各次交接（发起交接、逐轮退回、补充后
729	// 重新提交、确认接收或继续跟踪），无须先知道涉及哪些交接编号。
730	// 经过按实际发生时刻排序（带不同时区的时间按同一实际时刻比较）；同一时刻下
731	// 同一交接内保持发起、该轮退回、该轮重新提交、后续处理的先后，不同交接按
732	// 交接编号排列。同一次接收若已出现在事项历史里只展示一次。只读查询，
733	// 不改变事项、交接进度或班次结束时记录。
734	func (svc *Service) ItemJourney(itemID string) (ItemJourney, error) {
735		itemID = clean(itemID)
736		d := &svc.store.data
737		it, _ := findItem(d, itemID)
738		if it == nil {
739			return ItemJourney{}, fmt.Errorf("%w：事项 %s", ErrNotFound, itemID)
740		}
741		j := ItemJourney{Item: *it}
742	
743		// 排序键：先按实际发生时刻（未记录时间的排最后），同一时刻下事项自身
744		// 事件在前，其后按交接编号分组，组内保持生成顺序（发起、逐轮退回、
745		// 该轮重新提交、后续处理）。
746		type keyedEvent struct {
747			ev    JourneyEvent
748			group string // "" 表示事项自身事件，否则为交接编号
749			ord   int    // 同一（时刻、分组）内的先后
750		}
751		var events []keyedEvent
752		seq := 0
753		add := func(ev JourneyEvent, group string) {
754			events = append(events, keyedEvent{ev: ev, group: group, ord: seq})
755			seq++
756		}
757	
758		// received 事件与交接中的接收处理是同一次接收，只展示一次（以交接事件
759		// 展示，信息更全）；匹配不上的旧数据 received 事件仍原样保留。
760		receivedUsed := make([]bool, len(it.Events))
761	
762		hs := append([]Handover(nil), d.Handovers...)
763		sort.Slice(hs, func(i, k int) bool { return hs[i].ID < hs[k].ID })
764		for k := range hs {
765			h := &hs[k]
766			e, _ := findEntry(h, itemID)
767			if e == nil {
768				continue
769			}
770			j.HasHandovers = true
771			j.Results = append(j.Results, EntryView{
772				HandoverID: h.ID,
773				FromShift:  h.FromShiftID,
774				ToShift:    h.ToShiftID,
775				Entry:      *e,
776			})
777	
778			// 发起交接：交接记录本身不记操作人，明确显示未记录，不以班次负责人代替。
779			add(JourneyEvent{
780				At: h.CreatedAt, TimeKnown: !h.CreatedAt.IsZero(),
781				Kind: "handover-init", HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
782			}, h.ID)
783			for _, r := range e.Rounds {
784				add(JourneyEvent{
785					At: r.ReturnedAt, TimeKnown: !r.ReturnedAt.IsZero(),
786					Kind: "return", Operator: r.ReturnOperator,
787					HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
788					RoundSeq: r.Seq, Reason: r.Reason,
789				}, h.ID)
790				if r.ResubmittedAt != nil {
791					add(JourneyEvent{
792						At: *r.ResubmittedAt, TimeKnown: !r.ResubmittedAt.IsZero(),
793						Kind: "resubmit", Operator: r.SupplementOperator,
794						HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
795						RoundSeq: r.Seq, Supplement: r.Supplement,
796						SupplementOperator: r.SupplementOperator, SupplementAt: r.SupplementAt,
797					}, h.ID)
798				}
799			}
800			if e.Status.Received() {
801				kind := "confirm"
802				if e.Status == EntryTracking {
803					kind = "track"
804				}
805				ev := JourneyEvent{
806					Kind: kind, Operator: e.Operator,
807					HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
808					TrackingNote: e.TrackingNote,
809					// 继续跟踪当时指定的后续负责人取自交接记录快照，
810					// 之后修改事项负责人不改变这里的历史值。
811					FollowOwner: e.FollowOwner,
812				}
813				// 处理时间缺失或为旧数据零值时仍保留该处理事件，
814				// 时间标为未记录，排在有真实时间的事件之后。
815				if validProcessedAt(e.ProcessedAt) {
816					ev.At, ev.TimeKnown = *e.ProcessedAt, true
817				}
818				add(ev, h.ID)
819				if validProcessedAt(e.ProcessedAt) {
820					for i := range it.Events {
821						iev := &it.Events[i]
822						if iev.Kind == "received" && !receivedUsed[i] &&
823							iev.At.Equal(*e.ProcessedAt) && iev.Operator == e.Operator {
824							receivedUsed[i] = true
825							break
826						}
827					}
828				}
829			}
830		}
831	
832		// 事项自身历史：建立、修改、关闭原样保留；未被交接接收事件覆盖的
833		// received 事件（旧数据）也保留。
834		for i, iev := range it.Events {
835			if iev.Kind == "received" && receivedUsed[i] {
836				continue
837			}
838			add(JourneyEvent{
839				At: iev.At, TimeKnown: !iev.At.IsZero(),
840				Kind: iev.Kind, Operator: iev.Operator, Detail: iev.Detail,
841			}, "")
842		}
843	
844		sort.SliceStable(events, func(i, k int) bool {
845			a, b := events[i], events[k]
846			if a.ev.TimeKnown != b.ev.TimeKnown {
847				return a.ev.TimeKnown
848			}
849			if a.ev.TimeKnown && !a.ev.At.Equal(b.ev.At) {
850				return a.ev.At.Before(b.ev.At)
851			}
852			if a.group != b.group {
853				return a.group < b.group
854			}
855			return a.ord < b.ord
856		})
857		for _, ke := range events {
858			j.Events = append(j.Events, ke.ev)
859		}
860		return j, nil
861	}
862	
863	// GetHandover 按编号查询交接。
864	func (svc *Service) GetHandover(id string) (Handover, error) {
865		h, _ := findHandover(&svc.store.data, clean(id))
866		if h == nil {
867			return Handover{}, fmt.Errorf("%w：交接 %s", ErrNotFound, id)
868		}
869		return *h, nil
870	}
871	
872	// ListHandovers 返回全部交接记录，按编号排序。
873	func (svc *Service) ListHandovers() []Handover {
874		out := append([]Handover(nil), svc.store.data.Handovers...)
875		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
876		return out
877	}
878	
879	// OverlapNotes 返回涉及指定班次的全部重叠说明。
880	func (svc *Service) OverlapNotes(shiftID string) []OverlapNote {
881		shiftID = clean(shiftID)
882		out := []OverlapNote{}
883		for _, n := range svc.store.data.Notes {
884			if n.ShiftA == shiftID || n.ShiftB == shiftID {
885				out = append(out, n)
886			}
887		}
888		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
889		return out
890	}
891	
892	// ShiftReport 按班次汇总完整事项、关闭情况、接班对象、每项交接当前结果与历次退回/补充说明。
893	// 进行中的班次展示当前事项；已结束班次展示结束时冻结的事项记录，
894	// 旧数据中缺少结束时记录的班次只展示当前事项并标明历史不完整。
895	func (svc *Service) ShiftReport(shiftID string) (ShiftReport, error) {
896		shiftID = clean(shiftID)
897		d := &svc.store.data
898		rep := ShiftReport{Results: map[string][]EntryView{}, LatestItems: map[string]Item{}}
899		sh, _ := findShift(d, shiftID)
900		if sh == nil {
901			return ShiftReport{}, fmt.Errorf("%w：班次 %s", ErrNotFound, shiftID)
902		}
903		rep.Shift = *sh
904	
905		for _, n := range d.Notes {
906			if n.ShiftA == sh.ID || n.ShiftB == sh.ID {
907				rep.OverlapNotes = append(rep.OverlapNotes, n)
908			}
909		}
910		sort.Slice(rep.OverlapNotes, func(i, j int) bool { return rep.OverlapNotes[i].ID < rep.OverlapNotes[j].ID })
911	
912		switch {
913		case !sh.Closed:
914			// 进行中的班次：事项可继续修改、关闭，展示当前信息。
915			rep.Items = currentItemsOfShift(d, sh.ID)
916		case sh.CloseRecord != nil:
917			// 已结束且有结束时记录：展示冻结的结束时信息，并对照最新状态。
918			rep.ItemsAtClose = true
919			rep.CloseItems = append([]CloseItemSnapshot(nil), sh.CloseRecord.Items...)
920			sort.Slice(rep.CloseItems, func(i, j int) bool { return rep.CloseItems[i].ItemID < rep.CloseItems[j].ItemID })
921			for _, s := range rep.CloseItems {
922				if it, _ := findItem(d, s.ItemID); it != nil {
923					rep.LatestItems[s.ItemID] = *it
924				}
925			}
926		default:
927			// 旧数据：结束时未留下记录，只能展示当前信息，不能宣称是结束时事实。
928			rep.HistoryIncomplete = true
929			rep.Items = currentItemsOfShift(d, sh.ID)
930		}
931		sort.Slice(rep.Items, func(i, j int) bool { return rep.Items[i].ID < rep.Items[j].ID })
932	
933		for i := range d.Handovers {
934			h := &d.Handovers[i]
935			involved := h.FromShiftID == sh.ID || h.ToShiftID == sh.ID
936			if !involved {
937				continue
938			}
939			if h.FromShiftID == sh.ID {
940				cp := *h
941				rep.Outgoing = &cp
942			}
943			if h.ToShiftID == sh.ID {
944				rep.Incoming = append(rep.Incoming, *h)
945			}
946			for j := range h.Entries {
947				rep.Results[h.Entries[j].ItemID] = append(rep.Results[h.Entries[j].ItemID], EntryView{
948					HandoverID: h.ID,
949					FromShift:  h.FromShiftID,
950					ToShift:    h.ToShiftID,
951					Entry:      h.Entries[j],
952				})
953			}
954		}
955		sort.Slice(rep.Incoming, func(i, j int) bool { return rep.Incoming[i].ID < rep.Incoming[j].ID })
956		for k := range rep.Results {
957			sort.Slice(rep.Results[k], func(i, j int) bool { return rep.Results[k][i].HandoverID < rep.Results[k][j].HandoverID })
958		}
959		return rep, nil
960	}
