1	package handover
2	
3	import (
4		"fmt"
5		"sort"
6		"strings"
7		"time"
8	)
9	
10	const displayTime = "2006-01-02 15:04:05 -07:00"
11	
12	func fmtTime(t time.Time) string { return t.Format(displayTime) }
13	
14	func fmtTimePtr(t *time.Time) string {
15		if t == nil {
16			return "-"
17		}
18		return fmtTime(*t)
19	}
20	
21	// FormatShift 格式化班次摘要。
22	func FormatShift(sh Shift) string {
23		state := "进行中"
24		if sh.Closed {
25			state = "已结束 " + fmtTimePtr(sh.ClosedAt)
26		}
27		return fmt.Sprintf("%s  岗位=%s  负责人=%s  %s ~ %s  [%s]",
28			sh.ID, sh.Position, sh.Owner, fmtTime(sh.Start), fmtTime(sh.End), state)
29	}
30	
31	// FormatItem 格式化事项及其关闭情况与历史。
32	func FormatItem(it Item) string {
33		var b strings.Builder
34		writeItemHeader(&b, it)
35		if len(it.Events) > 0 {
36			b.WriteString("  历史：\n")
37			for _, ev := range it.Events {
38				who := ""
39				if ev.Operator != "" {
40					who = " 操作人=" + ev.Operator
41				}
42				detail := ""
43				if ev.Detail != "" {
44					detail = " " + ev.Detail
45				}
46				fmt.Fprintf(&b, "    - %s %s%s%s\n", fmtTime(ev.At), ev.Kind, who, detail)
47			}
48		}
49		return b.String()
50	}
51	
52	// writeItemHeader 输出事项的最新内容、严重程度、限制条件、后续负责人、
53	// 当前所在班次、关闭情况和流经班次。
54	func writeItemHeader(b *strings.Builder, it Item) {
55		state := "未关闭"
56		if it.Closed {
57			state = fmt.Sprintf("已关闭（%s 于 %s）", it.CloseOperator, fmtTimePtr(it.ClosedAt))
58		}
59		fmt.Fprintf(b, "%s  严重程度=%s  当前班次=%s  原始班次=%s  [%s]\n",
60			it.ID, it.Severity.Label(), it.CurrentShiftID, it.OriginShiftID, state)
61		fmt.Fprintf(b, "  内容：%s\n", it.Content)
62		fmt.Fprintf(b, "  限制条件：%s\n", dashIfEmpty(it.Constraints))
63		fmt.Fprintf(b, "  后续负责人：%s\n", it.FollowOwner)
64		fmt.Fprintf(b, "  流经班次：%s\n", strings.Join(it.ShiftIDs, " -> "))
65	}
66	
67	func dashIfEmpty(s string) string {
68		if s == "" {
69			return "-"
70		}
71		return s
72	}
73	
74	// whoIfRecorded 展示操作人，未记录时明确标为未记录，不以其他人代替。
75	func whoIfRecorded(s string) string {
76		if s == "" {
77			return "未记录"
78		}
79		return s
80	}
81	
82	// fmtTimePtrIfRecorded 展示时间指针，缺失时明确标为未记录。
83	func fmtTimePtrIfRecorded(t *time.Time) string {
84		if t == nil {
85			return "未记录"
86		}
87		return fmtTimeIfRecorded(*t)
88	}
89	
90	// fmtTimeIfRecorded 展示时间值，旧数据零值（0001-01-01T00:00:00Z）时
91	// 明确标为未记录，不显示公元元年日期。
92	func fmtTimeIfRecorded(t time.Time) string {
93		if t.IsZero() {
94			return "未记录"
95		}
96		return fmtTime(t)
97	}
98	
99	// fmtProcessedAtIfRecorded 展示处理时间，缺失（nil）或旧数据零值
100	// （0001-01-01T00:00:00Z）时明确标为未记录，不推测补齐。
101	func fmtProcessedAtIfRecorded(t *time.Time) string {
102		if t == nil || t.IsZero() {
103			return "未记录"
104		}
105		return fmtTime(*t)
106	}
107	
108	// currentProcessing 返回交接单项当前处理结果的处理人与处理时间展示，是
109	// 交接清单（handover-show、shift-show 内嵌清单与末尾结果说明）和事项处理
110	// 经过查询（item-show）共用的同一条业务规则。
111	//
112	// 是否处理过以已保存的处理结果（状态）为准，与处理时间是否保存无关：确认
113	// 接收、继续跟踪与退回都属于已经发生的处理，缺少处理时间不能使它们变成待
114	// 处理；真正待处理（含退回后已补充重新提交、等待接班人再次处理）的事项，
115	// 处理人与处理时间都显示尚未处理，即使旧记录残留姓名或时间也不显示成已处理。
116	//
117	// 已处理时处理人与处理时间各自独立展示：人名有值展示原姓名、缺失明确标为
118	// 未记录；时间有真实值沿用带时区格式、缺失或为旧数据零值
119	// （0001-01-01T00:00:00Z）同样标为未记录。缺少其中一个不能隐藏另一个，
120	// 也不以班次负责人、交接发起时间或退回历史中的信息代替。结果为空或无法
121	// 识别的记录同样按各自已保存的姓名与时间展示，不据以推测接收结果。
122	func currentProcessing(e HandoverEntry) (operator, processedAt string) {
123		if e.Status == EntryPending {
124			return "尚未处理", "尚未处理"
125		}
126		return whoIfRecorded(e.Operator), fmtProcessedAtIfRecorded(e.ProcessedAt)
127	}
128	
129	// entryCurrentResultLabel 是交接当前结果在事项处理经过查询中的展示名。
130	// 缺失或空结果显示“处理结果未记录”，无法识别的结果显示“处理结果无法识别”
131	// 并带出保存的原值，与交接清单、班次报告表达同一事实，不推测成已接收。
132	func entryCurrentResultLabel(s EntryStatus) string {
133		switch s {
134		case EntryPending:
135			return "待处理（接班人尚未处理）"
136		case EntryReturned:
137			return "退回（等待交班人补充）"
138		case EntryConfirmed:
139			return "确认接收"
140		case EntryTracking:
141			return "继续跟踪（已接收）"
142		case "":
143			return "处理结果未记录"
144		}
145		return "处理结果无法识别（原值：" + string(s) + "）"
146	}
147	
148	// FormatJourneyEvent 格式化处理经过中的单条记录。交接相关记录带有交接
149	// 编号与交班、接班班次；缺少的人名或时间明确标为未记录，不推测补齐。
150	func FormatJourneyEvent(ev JourneyEvent) string {
151		when := "未记录"
152		if ev.TimeKnown {
153			when = fmtTime(ev.At)
154		}
155		who := whoIfRecorded(ev.Operator)
156		where := ""
157		if ev.HandoverID != "" {
158			where = fmt.Sprintf("交接 %s（%s -> %s）", ev.HandoverID, ev.FromShift, ev.ToShift)
159		}
160		switch ev.Kind {
161		case "created":
162			return when + " 事项建立"
163		case "updated":
164			return fmt.Sprintf("%s 修改：%s", when, ev.Detail)
165		case "closed":
166			return fmt.Sprintf("%s 关闭 操作人=%s", when, who)
167		case "received":
168			return fmt.Sprintf("%s 接收 操作人=%s %s", when, who, ev.Detail)
169		case "handover-init":
170			// 交接发起不记录操作人，始终显示未记录，不以班次负责人代替。
171			return fmt.Sprintf("%s %s发起交接 操作人=%s", when, where, who)
172		case "return":
173			return fmt.Sprintf("%s %s第%d次退回 操作人=%s 原因=%s",
174				when, where, ev.RoundSeq, who, ev.Reason)
175		case "resubmit":
176			return fmt.Sprintf("%s %s第%d次重新提交 补充说明=%s 补充人=%s 补充时间=%s",
177				when, where, ev.RoundSeq, dashIfEmpty(ev.Supplement),
178				whoIfRecorded(ev.SupplementOperator), fmtTimePtrIfRecorded(ev.SupplementAt))
179		case "confirm":
180			return fmt.Sprintf("%s %s确认接收 操作人=%s", when, where, who)
181		case "track":
182			return fmt.Sprintf("%s %s继续跟踪 操作人=%s 跟踪说明=%s 后续负责人=%s",
183				when, where, who, dashIfEmpty(ev.TrackingNote), dashIfEmpty(ev.FollowOwner))
184		}
185		return when + " " + ev.Kind
186	}
187	
188	// FormatItemJourney 格式化凭事项编号查询得到的完整处理经过：开头为事项
189	// 最新状态，随后是合并事项自身历史与各次交接经过的时间线，最后列出该事项
190	// 在每次交接中的当前处理结果；尚未参与交接的显示暂无交接记录。
191	func FormatItemJourney(j ItemJourney) string {
192		var b strings.Builder
193		writeItemHeader(&b, j.Item)
194	
195		b.WriteString("  处理经过：\n")
196		if len(j.Events) == 0 {
197			b.WriteString("    （暂无记录）\n")
198		}
199		for _, ev := range j.Events {
200			b.WriteString("    - " + FormatJourneyEvent(ev) + "\n")
201		}
202	
203		b.WriteString("  交接当前结果：\n")
204		if !j.HasHandovers {
205			b.WriteString("    暂无交接记录\n")
206		}
207		for _, r := range j.Results {
208			// 处理人与处理时间沿用共用的当前处理展示规则（见 currentProcessing）。
209			operator, processedAt := currentProcessing(r.Entry)
210			fmt.Fprintf(&b, "    交接 %s（%s -> %s）当前结果：%s；处理人=%s；处理时间=%s\n",
211				r.HandoverID, r.FromShift, r.ToShift,
212				entryCurrentResultLabel(r.Entry.Status), operator, processedAt)
213		}
214		return b.String()
215	}
216	
217	// FormatCloseItem 格式化班次结束时冻结的事项记录，并与最新状态对照。
218	func FormatCloseItem(snap CloseItemSnapshot, latest *Item) string {
219		var b strings.Builder
220		state := "结束时未关闭"
221		if snap.Closed {
222			state = fmt.Sprintf("结束时已关闭（%s 于 %s）", snap.CloseOperator, fmtTimePtr(snap.ClosedAt))
223		}
224		fmt.Fprintf(&b, "%s  严重程度=%s  %s\n", snap.ItemID, snap.Severity.Label(), state)
225		fmt.Fprintf(&b, "  内容：%s\n", snap.Content)
226		fmt.Fprintf(&b, "  限制条件：%s\n", dashIfEmpty(snap.Constraints))
227		fmt.Fprintf(&b, "  结束时后续负责人：%s\n", snap.FollowOwner)
228		if latest == nil {
229			b.WriteString("  最新状态：事项记录已不存在\n")
230			return b.String()
231		}
232		closeState := "未关闭"
233		if latest.Closed {
234			closeState = fmt.Sprintf("已关闭（%s 于 %s）", latest.CloseOperator, fmtTimePtr(latest.ClosedAt))
235		}
236		fmt.Fprintf(&b, "  最新状态：当前所在班次=%s  最新负责人=%s  最新关闭情况=%s\n",
237			latest.CurrentShiftID, latest.FollowOwner, closeState)
238		return b.String()
239	}
240	
241	// FormatOverlapNote 格式化重叠说明。
242	func FormatOverlapNote(n OverlapNote) string {
243		return fmt.Sprintf("%s  岗位=%s  班次 %s <-> %s  %s\n  说明：%s",
244			n.ID, n.Position, n.ShiftA, n.ShiftB, fmtTime(n.CreatedAt), n.Note)
245	}
246	
247	// FormatEntry 格式化交接单项当前结果与历次退回、补充说明。
248	func FormatEntry(e HandoverEntry) string {
249		var b strings.Builder
250		fmt.Fprintf(&b, "%s  [%s]  严重程度=%s  后续负责人=%s\n",
251			e.ItemID, e.Status.Label(), e.Severity.Label(), e.FollowOwner)
252		fmt.Fprintf(&b, "  原文：%s\n", e.Content)
253		fmt.Fprintf(&b, "  限制条件：%s\n", dashIfEmpty(e.Constraints))
254		// 处理人与处理时间沿用共用的当前处理展示规则（见 currentProcessing）；
255		// 待处理项在此额外说明等待接班人处理。
256		operator, processedAt := currentProcessing(e)
257		if e.Status == EntryPending {
258			fmt.Fprintf(&b, "  最后处理：尚未处理（等待接班人处理）；处理人=%s；处理时间=%s\n",
259				operator, processedAt)
260		} else {
261			fmt.Fprintf(&b, "  最后处理：处理人=%s；处理时间=%s\n", operator, processedAt)
262		}
263		if e.Status == EntryTracking || e.TrackingNote != "" {
264			fmt.Fprintf(&b, "  跟踪说明：%s\n", dashIfEmpty(e.TrackingNote))
265			fmt.Fprintf(&b, "  跟踪后续负责人：%s\n", dashIfEmpty(e.FollowOwner))
266		}
267		for _, r := range e.Rounds {
268			fmt.Fprintf(&b, "  第%d次退回：%s 操作人=%s 原因=%s\n",
269				r.Seq, fmtTimeIfRecorded(r.ReturnedAt),
270				whoIfRecorded(r.ReturnOperator), r.Reason)
271			if r.Supplement != "" {
272				fmt.Fprintf(&b, "    补充说明：%s 补充人=%s 补充时间=%s\n",
273					r.Supplement, whoIfRecorded(r.SupplementOperator),
274					fmtTimePtrIfRecorded(r.SupplementAt))
275			}
276			if r.ResubmittedAt != nil {
277				fmt.Fprintf(&b, "    已重新提交：%s\n", fmtTimePtrIfRecorded(r.ResubmittedAt))
278			}
279		}
280		return b.String()
281	}
282	
283	// FormatHandover 格式化完整交接记录。
284	func FormatHandover(h Handover) string {
285		var b strings.Builder
286		state := "未完成"
287		if h.Completed() {
288			state = "已完成 " + fmtTimePtrIfRecorded(h.CompletedAt)
289		}
290		fmt.Fprintf(&b, "%s  岗位=%s  %s -> %s  发起于 %s  [%s]  共%d项\n",
291			h.ID, h.Position, h.FromShiftID, h.ToShiftID,
292			fmtTimeIfRecorded(h.CreatedAt), state, len(h.Entries))
293		if len(h.Entries) == 0 {
294			b.WriteString("  （空清单，直接完成）\n")
295		}
296		for i := range h.Entries {
297			b.WriteString(indentLines(FormatEntry(h.Entries[i]), "  "))
298		}
299		return b.String()
300	}
301	
302	func indentLines(s, prefix string) string {
303		return prefix + strings.ReplaceAll(strings.TrimRight(s, "\n"), "\n", "\n"+prefix) + "\n"
304	}
305	
306	// FormatReport 格式化按班次查询的完整报告。
307	func FormatReport(rep ShiftReport) string {
308		var b strings.Builder
309		b.WriteString("班次 " + FormatShift(rep.Shift) + "\n")
310	
311		b.WriteString("\n重叠说明：\n")
312		if len(rep.OverlapNotes) == 0 {
313			b.WriteString("  （无）\n")
314		}
315		for _, n := range rep.OverlapNotes {
316			b.WriteString(indentLines(FormatOverlapNote(n), "  "))
317		}
318	
319		if rep.ItemsAtClose {
320			b.WriteString("\n事项（以下为结束时记录，冻结于该班结束成功时刻；后班的修改、关闭与交接不改变本记录）：\n")
321			if len(rep.CloseItems) == 0 {
322				b.WriteString("  （结束时没有事项）\n")
323			}
324			for _, s := range rep.CloseItems {
325				var latest *Item
326				if v, ok := rep.LatestItems[s.ItemID]; ok {
327					latest = &v
328				}
329				b.WriteString(indentLines(FormatCloseItem(s, latest), "  "))
330			}
331		} else {
332			if rep.HistoryIncomplete {
333				b.WriteString("\n事项（历史记录不完整，该班结束时未留下记录，以下为当前信息，不能视为结束时事实）：\n")
334			} else {
335				b.WriteString("\n事项：\n")
336			}
337			if len(rep.Items) == 0 {
338				b.WriteString("  （无）\n")
339			}
340			for _, it := range rep.Items {
341				b.WriteString(indentLines(FormatItem(it), "  "))
342			}
343		}
344	
345		b.WriteString("\n交班对象：\n")
346		if rep.Outgoing == nil {
347			b.WriteString("  （尚未发起交接）\n")
348		} else {
349			b.WriteString(indentLines(FormatHandover(*rep.Outgoing), "  "))
350		}
351	
352		b.WriteString("\n接班交接：\n")
353		if len(rep.Incoming) == 0 {
354			b.WriteString("  （无）\n")
355		}
356		for _, h := range rep.Incoming {
357			b.WriteString(indentLines(FormatHandover(h), "  "))
358		}
359	
360		b.WriteString("\n各项交接当前结果：\n")
361		if len(rep.Results) == 0 {
362			b.WriteString("  （无）\n")
363		}
364		ids := make([]string, 0, len(rep.Results))
365		for id := range rep.Results {
366			ids = append(ids, id)
367		}
368		sort.Strings(ids)
369		for _, id := range ids {
370			views := rep.Results[id]
371			for _, v := range views {
372				// 处理人与处理时间沿用共用的当前处理展示规则（见
373				// currentProcessing），与内嵌交接清单表达同一事实。
374				operator, processedAt := currentProcessing(v.Entry)
375				fmt.Fprintf(&b, "  事项 %s 交接 %s（%s -> %s）当前结果：%s；处理人=%s；处理时间=%s\n",
376					id, v.HandoverID, v.FromShift, v.ToShift,
377					v.Entry.Status.Label(), operator, processedAt)
378				for _, r := range v.Entry.Rounds {
379					fmt.Fprintf(&b, "    第%d次退回：操作人=%s 时间=%s 原因=%s\n",
380						r.Seq, whoIfRecorded(r.ReturnOperator),
381						fmtTimeIfRecorded(r.ReturnedAt), r.Reason)
382					if r.Supplement != "" {
383						fmt.Fprintf(&b, "      补充：%s（补充人=%s，补充时间=%s）\n",
384							r.Supplement, whoIfRecorded(r.SupplementOperator),
385							fmtTimePtrIfRecorded(r.SupplementAt))
386					}
387					if r.ResubmittedAt != nil {
388						fmt.Fprintf(&b, "      已重新提交：%s\n", fmtTimePtrIfRecorded(r.ResubmittedAt))
389					}
390				}
391			}
392		}
393		return b.String()
394	}
